     1	package hotel.web;
     2	
     3	import com.fasterxml.jackson.databind.ObjectMapper;
     4	import com.fasterxml.jackson.databind.SerializationFeature;
     5	import com.fasterxml.jackson.databind.json.JsonMapper;
     6	import com.fasterxml.jackson.datatype.jsr310.JavaTimeModule;
     7	import hotel.messages.SentMessages;
     8	import hotel.reports.OccupancyReport;
     9	import hotel.reports.RatePlanReport;
    10	import hotel.reports.RevenueReport;
    11	import hotel.reports.TourismTaxReport;
    12	import hotel.reservations.ErrorCode;
    13	import hotel.reservations.Guest;
    14	import hotel.reservations.HotelException;
    15	import hotel.reservations.NewReservation;
    16	import hotel.reservations.ReservationService;
    17	import hotel.rooms.Rooms;
    18	import io.javalin.Javalin;
    19	import io.javalin.http.Context;
    20	import io.javalin.json.JavalinJackson;
    21	import java.time.LocalDate;
    22	import java.time.YearMonth;
    23	import java.time.format.DateTimeParseException;
    24	
    25	/** The HTTP API the inn's website and front desk call. */
    26	public final class HttpApi {
    27	
    28	    private final Javalin server;
    29	    private final Rooms rooms;
    30	    private final ReservationService reservations;
    31	    private final SentMessages sentMessages;
    32	    private final OccupancyReport occupancyReport;
    33	    private final RevenueReport revenueReport;
    34	    private final TourismTaxReport tourismTaxReport;
    35	    private final RatePlanReport ratePlanReport;
    36	
    37	    public HttpApi(
    38	            Rooms rooms,
    39	            ReservationService reservations,
    40	            SentMessages sentMessages,
    41	            OccupancyReport occupancyReport,
    42	            RevenueReport revenueReport,
    43	            TourismTaxReport tourismTaxReport,
    44	            RatePlanReport ratePlanReport) {
    45	        this.rooms = rooms;
    46	        this.reservations = reservations;
    47	        this.sentMessages = sentMessages;
    48	        this.occupancyReport = occupancyReport;
    49	        this.revenueReport = revenueReport;
    50	        this.tourismTaxReport = tourismTaxReport;
    51	        this.ratePlanReport = ratePlanReport;
    52	
    53	        ObjectMapper jsonMapper = JsonMapper.builder()
    54	                .addModule(new JavaTimeModule())
    55	                .disable(SerializationFeature.WRITE_DATES_AS_TIMESTAMPS)
    56	                .build();
    57	        this.server = Javalin.create(config -> {
    58	            config.showJavalinBanner = false;
    59	            config.jsonMapper(new JavalinJackson(jsonMapper, false));
    60	        });
    61	        registerRoutes();
    62	        registerErrorHandling();
    63	    }
    64	
    65	    public Javalin server() {
    66	        return server;
    67	    }
    68	
    69	    private void registerRoutes() {
    70	        server.get("/rooms", ctx -> ctx.json(rooms.all()));
    71	
    72	        server.post("/reservations", ctx -> {
    73	            NewReservation request = readNewReservation(ctx);
    74	            ctx.status(201).json(new ReservationResponse(reservations.create(request)));
    75	        });
    76	        server.get("/reservations/{id}", ctx ->
    77	                ctx.json(new ReservationResponse(reservations.find(reservationId(ctx)))));
    78	        server.post("/reservations/{id}/confirmation", ctx ->
    79	                ctx.json(new ReservationResponse(reservations.confirm(reservationId(ctx)))));
    80	        server.post("/reservations/{id}/cancellation", ctx ->
    81	                ctx.json(new ReservationResponse(reservations.cancel(reservationId(ctx)))));
    82	        server.post("/reservations/{id}/check-in", ctx ->
    83	                ctx.json(new ReservationResponse(reservations.checkIn(reservationId(ctx)))));
    84	        server.post("/reservations/{id}/check-out", ctx ->
    85	                ctx.json(reservations.checkOut(reservationId(ctx))));
    86	        server.get("/reservations/{id}/document", ctx ->
    87	                ctx.json(reservations.receiptCopy(reservationId(ctx))));
    88	
    89	        server.get("/messages", ctx -> ctx.json(sentMessages.all()));
    90	
    91	        server.get("/reports/occupancy", ctx -> {
    92	            LocalDate night = readDate(ctx);
    93	            ctx.contentType("text/csv; charset=utf-8").result(occupancyReport.generate(night));
    94	        });
    95	        server.get("/reports/revenue", ctx -> {
    96	            YearMonth month = readMonth(ctx);
    97	            ctx.contentType("text/csv; charset=utf-8").result(revenueReport.generate(month));
    98	        });
    99	        server.get("/reports/tourism-tax", ctx -> {
   100	            YearMonth month = readMonth(ctx);
   101	            ctx.contentType("text/csv; charset=utf-8").result(tourismTaxReport.generate(month));
   102	        });
   103	        server.get("/reports/rate-plans", ctx -> {
   104	            YearMonth month = readMonth(ctx);
   105	            ctx.contentType("text/csv; charset=utf-8").result(ratePlanReport.generate(month));
   106	        });
   107	    }
   108	
   109	    private void registerErrorHandling() {
   110	        server.exception(HotelException.class, (exception, ctx) -> {
   111	            ctx.status(httpStatus(exception.errorCode()));
   112	            ctx.json(new ErrorResponse(exception.errorCode().name(), exception.getMessage()));
   113	        });
   114	    }
   115	
   116	    private static int httpStatus(ErrorCode errorCode) {
   117	        return switch (errorCode) {
   118	            case INVALID_REQUEST -> 400;
   119	            case ROOM_NOT_FOUND, RESERVATION_NOT_FOUND -> 404;
   120	            case ROOM_UNAVAILABLE, OPERATION_NOT_ALLOWED -> 409;
   121	            case CAPACITY_EXCEEDED -> 422;
   122	        };
   123	    }
   124	
   125	    private static NewReservation readNewReservation(Context ctx) {
   126	        CreateReservationRequest body;
   127	        try {
   128	            body = ctx.bodyAsClass(CreateReservationRequest.class);
   129	        } catch (Exception unreadableBody) { // Jackson's own exceptions are checked, but reach here unwrapped
   130	            throw new HotelException(ErrorCode.INVALID_REQUEST, "the body is not a valid reservation request");
   131	        }
   132	        if (body == null
   133	                || body.roomNumber() == null
   134	                || isBlank(body.guestName())
   135	                || isBlank(body.guestEmail())
   136	                || isBlank(body.guestCpf())
   137	                || body.checkIn() == null
   138	                || body.checkOut() == null
   139	                || body.guests() == null
   140	                || body.ratePlan() == null) {
   141	            throw new HotelException(ErrorCode.INVALID_REQUEST, "every field of the reservation is required");
   142	        }
   143	        Guest guest = new Guest(body.guestName(), body.guestEmail(), body.guestCpf());
   144	        return new NewReservation(
   145	                body.roomNumber(), guest, body.checkIn(), body.checkOut(), body.guests(), body.ratePlan());
   146	    }
   147	
   148	    private static long reservationId(Context ctx) {
   149	        String id = ctx.pathParam("id");
   150	        try {
   151	            return Long.parseLong(id);
   152	        } catch (NumberFormatException notANumber) {
   153	            throw new HotelException(ErrorCode.RESERVATION_NOT_FOUND, "reservation " + id + " does not exist");
   154	        }
   155	    }
   156	
   157	    private static LocalDate readDate(Context ctx) {
   158	        String date = requiredQueryParam(ctx, "date");
   159	        try {
   160	            return LocalDate.parse(date);
   161	        } catch (DateTimeParseException badDate) {
   162	            throw new HotelException(ErrorCode.INVALID_REQUEST, "'" + date + "' is not a date (yyyy-MM-dd)");
   163	        }
   164	    }
   165	
   166	    private static YearMonth readMonth(Context ctx) {
   167	        String month = requiredQueryParam(ctx, "month");
   168	        try {
   169	            return YearMonth.parse(month);
   170	        } catch (DateTimeParseException badMonth) {
   171	            throw new HotelException(ErrorCode.INVALID_REQUEST, "'" + month + "' is not a month (yyyy-MM)");
   172	        }
   173	    }
   174	
   175	    private static String requiredQueryParam(Context ctx, String name) {
   176	        String value = ctx.queryParam(name);
   177	        if (value == null) {
   178	            throw new HotelException(ErrorCode.INVALID_REQUEST, "the query parameter '" + name + "' is required");
   179	        }
   180	        return value;
   181	    }
   182	
   183	    private static boolean isBlank(String text) {
   184	        return text == null || text.isBlank();
   185	    }
   186	}
