   158	        String date = requiredQueryParam(ctx, "date");
   159	        try {
   160	            return LocalDate.parse(date);
   161	        } catch (DateTimeParseException badDate) {
   162	            throw new HotelException(ErrorCode.INVALID_REQUEST, "'" + date + "' is not a date (yyyy-MM-dd)");
   163	        }
   164	    }
