288	    private HttpResponse<String> post(String path, String body) throws IOException, InterruptedException {
289	        return client.send(HttpRequest.newBuilder(URI.create(baseUrl + path))
290	                        .header("Content-Type", "application/json")
291	                        .POST(HttpRequest.BodyPublishers.ofString(body))
292	                        .build(),
293	                HttpResponse.BodyHandlers.ofString());
294	    }
