257	class HttpApiTest {
258	
259	    private static final String RESERVATION_JSON = """
260	            {"roomNumber": 201, "guestName": "Carla Dias", "guestEmail": "carla@example.com",
261	             "guestCpf": "111.222.333-44", "checkIn": "2027-07-10", "checkOut": "2027-07-12",
262	             "guests": 2, "ratePlan": "STANDARD"}
263	            """;
264	
265	    private final HttpClient client = HttpClient.newHttpClient();
266	    private final ObjectMapper json = new ObjectMapper();
267	    private final EmptyDatabase database = new EmptyDatabase();
268	    private Hotel hotel;
269	    private String baseUrl;
270	
271	    @BeforeEach
272	    void startHotel() {
273	        hotel = new Hotel(database.dataSource());
274	        baseUrl = "http://localhost:" + hotel.start(0);
275	    }
276	
277	    @AfterEach
278	    void stopHotel() {
279	        hotel.stop();
280	        database.close();
281	    }
282	
283	    private HttpResponse<String> get(String path) throws IOException, InterruptedException {
284	        return client.send(HttpRequest.newBuilder(URI.create(baseUrl + path)).GET().build(),
285	                HttpResponse.BodyHandlers.ofString());
286	    }
287	
288	    private HttpResponse<String> post(String path, String body) throws IOException, InterruptedException {
289	        return client.send(HttpRequest.newBuilder(URI.create(baseUrl + path))
290	                        .header("Content-Type", "application/json")
291	                        .POST(HttpRequest.BodyPublishers.ofString(body))
292	                        .build(),
293	                HttpResponse.BodyHandlers.ofString());
294	    }
