296	    @Test
297	    void listsTheRooms() throws Exception {
298	        HttpResponse<String> response = get("/rooms");
299	
300	        assertEquals(200, response.statusCode());
301	        JsonNode rooms = json.readTree(response.body());
302	        assertEquals(5, rooms.size());
303	        assertEquals(101, rooms.get(0).get("number").asInt());
304	        assertEquals("249.9", rooms.get(0).get("nightlyRate").asText());
305	    }
