307	    @Test
308	    void booksConfirmsAndChecksOut() throws Exception {
309	        HttpResponse<String> created = post("/reservations", RESERVATION_JSON);
310	        assertEquals(201, created.statusCode());
311	        JsonNode reservation = json.readTree(created.body());
312	        long id = reservation.get("id").asLong();
313	        assertEquals("PENDING", reservation.get("status").asText());
314	        assertEquals("2027-07-10", reservation.get("checkIn").asText());
315	        assertEquals(935.76, reservation.get("total").asDouble());
316	
317	        assertEquals(200, post("/reservations/" + id + "/confirmation", "").statusCode());
318	        JsonNode messages = json.readTree(get("/messages").body());
319	        assertEquals(1, messages.size());
320	        assertEquals("carla@example.com", messages.get(0).get("to").asText());
321	
322	        assertEquals(200, post("/reservations/" + id + "/check-in", "").statusCode());
323	        HttpResponse<String> checkedOut = post("/reservations/" + id + "/check-out", "");
324	        assertEquals(200, checkedOut.statusCode());
325	        assertEquals("Comprovante de reserva", json.readTree(checkedOut.body()).get("title").asText());
326	        assertEquals("CHECKED_OUT", json.readTree(get("/reservations/" + id).body()).get("status").asText());
327	    }
328	
329	    @Test
330	    void answersErrorsWithACode() throws Exception {
331	        HttpResponse<String> missingFields = post("/reservations", "{\"roomNumber\": 201}");
332	        assertEquals(400, missingFields.statusCode());
333	        assertEquals("INVALID_REQUEST", json.readTree(missingFields.body()).get("error").asText());
334	
335	        assertEquals(400, post("/reservations", "not json").statusCode());
336	        assertEquals(400, post("/reservations", RESERVATION_JSON.replace("STANDARD", "VIP")).statusCode());
337	        assertEquals(404, get("/reservations/42").statusCode());
338	        assertEquals(404, get("/reservations/abc").statusCode());
339	
340	        post("/reservations", RESERVATION_JSON);
341	        HttpResponse<String> taken = post("/reservations", RESERVATION_JSON);
342	        assertEquals(409, taken.statusCode());
343	        assertEquals("ROOM_UNAVAILABLE", json.readTree(taken.body()).get("error").asText());
344	    }
