346	    @Test
347	    void servesTheReportsAsCsv() throws Exception {
348	        long id = json.readTree(post("/reservations", RESERVATION_JSON).body()).get("id").asLong();
349	        post("/reservations/" + id + "/confirmation", "");
350	
351	        HttpResponse<String> occupancy = get("/reports/occupancy?date=2027-07-11");
352	        assertEquals(200, occupancy.statusCode());
353	        assertTrue(occupancy.headers().firstValue("Content-Type").orElse("").startsWith("text/csv"));
354	        assertTrue(occupancy.body().endsWith("total,1/5\n"));
355	
356	        assertTrue(get("/reports/revenue?month=2027-07").body().endsWith("total,935.76\n"));
357	        assertEquals(400, get("/reports/revenue?month=july").statusCode());
358	        assertEquals(400, get("/reports/occupancy").statusCode());
359	    }
